# To run this code you need to install the following dependencies:
# pip install google-genai

import base64
import os
from google import genai
from google.genai import types


def generate():
    client = genai.Client(
        api_key=os.environ.get("GEMINI_API_KEY"),
    )

    model = "gemini-2.5-pro"
    contents = [
        types.Content(
            role="user",
            parts=[
                types.Part.from_bytes(
                    mime_type="image/jpeg",
                    data=base64.b64decode(
                        """"""
                    ),
                ),
                types.Part.from_text(text="""What is in this image?"""),
            ],
        ),
        types.Content(
            role="model",
            parts=[
                types.Part.from_text(text="""**Defining the Image's Focus**

I've homed in on the core of the image: three young figures. I see them shoulder-to-shoulder, striking a pose. The central figure steps forward, taking the lead.


**Observing the Details**

I've noted the subjects are three young women. The central figure, seemingly of mixed race, strikes a pose with crossed arms and a serious expression. The East Asian woman on the left gazes at the camera, and the other, details pending further scrutiny.


**Examining the Scene**

I'm now diving into the finer points. The central figure, with braided hair and a graphic tee, holds a commanding pose. The East Asian woman on the left, in her red ensemble, meets the camera's gaze. The final figure, with a slight smile, is the final component of the image. The setting looks like a house with simple light-colored walls and flooring, suggesting the image is a capture from a typical residential room. The overall impression is one of casual camaraderie.


**Analyzing the Composition**

I've crafted a comprehensive description. The image features three young women, center-focused. The central figure, with long braids and a black tee, strikes a pose, while a woman in red gazes at the camera, and another in black smiles. The setting appears to be a residential room with light walls and flooring.


**Describing the Composition**

I'm developing a unified description of the image. The focus is on three young women, positioned centrally. The central figure, with long braids, sports a black graphic tee, crossed arms, and a serious expression. To her left, a woman in red gazes at the camera. On the right, another woman in black smiles. The setting is a simple residential room with light walls and flooring. The vertical aspect ratio and casual vibe suggest a social media video capture.


"""),
                types.Part.from_text(text="""Based on the image and the provided crops, here is a description of what is shown:

This is an indoor photograph of three young women posing for the camera, likely a still from a video.

*   **In the center,** a young Black girl with long braids is the main focus. She is wearing a black t-shirt with a white graphic and black pants. She is making a hand gesture with both hands, crossing her arms and pointing her index and middle fingers outwards. She has a pouting or serious expression on her face.

*   **To the left,** an East Asian young woman with long, dark hair and large hoop earrings stands looking at the camera. She is wearing a red off-the-shoulder top and a red, black, and white plaid mini skirt.

*   **To the right,** another young Black girl with glasses and long braids is smiling. She is wearing a black long-sleeved crop top and matching black flared pants. Her right hand is raised near her face.

They appear to be in a room with light-colored walls and a light-colored carpeted floor. The overall impression is that of friends posing for a social media video or photo."""),
            ],
        ),
        types.Content(
            role="user",
            parts=[
                types.Part.from_text(text="""INSERT_INPUT_HERE"""),
            ],
        ),
    ]
    generate_content_config = types.GenerateContentConfig(
        thinking_config = types.ThinkingConfig(
            thinking_budget=-1,
        ),
        response_mime_type="text/plain",
    )

    for chunk in client.models.generate_content_stream(
        model=model,
        contents=contents,
        config=generate_content_config,
    ):
        print(chunk.text, end="")

if __name__ == "__main__":
    generate()
